from typing import List

def minValidStrings(words: List[str], target: str) -> int:
    # Build a set of all prefixes
    prefix_set = set()
    for w in words:
        for i in range(1, len(w) + 1):
            prefix_set.add(w[:i])

    n = len(target)
    # dp[i] = min number of valid strings to form target[:i]
    dp = [float('inf')] * (n + 1)
    dp[0] = 0

    for i in range(1, n + 1):
        # Try all possible prefix lengths
        for j in range(1, min(i, 5000) + 1):
            if target[i - j:i] in prefix_set:
                if dp[i - j] + 1 < dp[i]:
                    dp[i] = dp[i - j] + 1

    return dp[n] if dp[n] != float('inf') else -1
