    n = len(s)

    # Score matrix: score[bob][alice] = points Bob gets
    # F=0, W=1, E=2
    # Bob F vs Alice F: 0, W: 1 (W beats F), E: -1 (E loses to F, so Bob gets -1)
    # Bob W vs Alice F: 1, W: 0, E: -1
    # Bob E vs Alice F: -1, W: 1, E: 0
    score = {
        'F': {'F': 0, 'W': 1, 'E': -1},
        'W': {'F': 1, 'W': 0, 'E': -1},
        'E': {'F': -1, 'W': 1, 'E': 0},
    }

    # dp[i][last_bob][diff] where diff = bob_score - alice_score
    # diff can range from -n to n
    # Use offset
    offset = n
    max_diff = 2 * n + 1

    # dp[last_bob][diff] = number of ways
    # Initialize for i=0
    dp = [[[0] * max_diff for _ in range(3)] for _ in range(n)]

    for i in range(n):
        for last in range(3):
            diff = score[chr(ord('F') + last)][s[i]]
            dp[i][last][diff + offset] = 1

    for i in range(1, n):
